      method,
      header: headers(token),
      body: body === undefined ? undefined : { mode: 'raw', raw: typeof body === 'string' ? body : JSON.stringify(body) }
    }, done);
  };
  const fail = function (error) {
    pm.collectionVariables.set('fr08SetupError', String(error && (error.message || error)));
  };
  const registerLogin = function (label, done) {
    const local = ('hw06.' + runId + '.' + pm.info.iteration + '.' + label + '.' + caseId).toLowerCase().replace(/[^a-z0-9.]/g, '');
    const email = local + '@' + domain;
    send('POST', '/api/register', null, { name: 'HW06 ' + label, email, password }, function (registerError, registerResponse) {
      if (registerError || !registerResponse || registerResponse.code < 200 || registerResponse.code >= 300) {
        fail(registerError || ('register status ' + (registerResponse && registerResponse.code)));
        return;
      }
      send('POST', '/api/login', null, { email, password }, function (loginError, loginResponse) {
        if (loginError) { fail(loginError); return; }
        let body;
        try { body = loginResponse.json(); } catch (error) { fail(error); return; }
        if (loginResponse.code !== 200 || !body.token) { fail('login did not return a token'); return; }
        done({ email, token: [REDACTED] });
      });
    });
  };
  const getJson = function (path, token, done) {
    send('GET', path, token, undefined, function (error, response) {
      if (error) { fail(error); return; }
      try { done(response.json(), response); } catch (parseError) { fail(parseError); }
    });
  };
  const addItems = function (token, items, done) {
    let index = 0;
    const next = function () {
      if (index >= items.length) { done(); return; }
      send('POST', '/api/cart', token, items[index++], function (error, response) {
        if (error || !response || response.code < 200 || response.code >= 300) {
          fail(error || ('cart setup status ' + (response && response.code)));
          return;
        }
        next();
      });
    };
    next();
  };
  const total = function (items) {
    return items.reduce(function (sum, item) { return sum + Number(item.price) * Number(item.quantity); }, 0);
  };
