    getJson('/api/orders/my-orders', account.token, function (beforeOrders) {
      getJson('/api/cart', account.token, function () {
        addItems(account.token, items, function () {
          getJson('/api/cart', account.token, function (cart) {
            done({ account, beforeOrders, cart, serverTotal: total(cart) });
          });
        });
      });
    });
  };
  const storeFixture = function (label, value) {
    pm.collectionVariables.set('caseUserToken' + label, value.account.token);
