    pm.collectionVariables.set('fr08BeforeCart' + label, JSON.stringify(value.cart));
    pm.collectionVariables.set('fr08ServerTotal' + label, String(value.serverTotal));
  };
  const prepareBody = function () {
    const body = pm.iterationData.get('checkoutBody');
    let raw = pm.iterationData.get('malformedBody');
