    const invalidKid = b64url(JSON.stringify({ alg: 'HS256', typ: 'JWT', kid: 'missing-key' })) + '.' + b64url(JSON.stringify(payload)) + '.invalid-signature';
    return { tampered, none, invalidKid };
  };
  const adminEmail = [REDACTED]
  const adminPassword = [REDACTED]
  login(adminEmail, adminPassword, function (admin) {
    pm.collectionVariables.set('caseAdminToken', admin.token);
    registerUser('a', function (userA) {
