              pm.variables.set('caseOrderId', String(selectedId));
              pm.variables.set('statusRaw', pm.iterationData.get('statusBody') == null ? '{}' : pm.iterationData.get('statusBody'));
              const setupKey = pm.iterationData.get('setupKey');
